        frame = BlzCreateFrame("TasButtonTextTemplate", parent, 0, 0)
        BlzFrameSetPoint(frame, FRAMEPOINT_TOPLEFT, parent, FRAMEPOINT_TOPLEFT, boxRefBorderGap, -boxRefBorderGap)
