FogModifierStart(GetLastCreatedFogModifier())
FogModifierStop(GetLastCreatedFogModifier())
DestroyFogModifier(GetLastCreatedFogModifier())
udg_TempInt = udg_TempInt + 1
end
udg_TempInt = 1
while (true) do
if (udg_TempInt > udg_MaxNumPlayers) then break end
