    y2 = GetItemY(udg_CP_Item)
    SetItemVisible(udg_CP_Item, false)
    while (udg_CP_HiddenItemsIndex > 0) do
    udg_CP_HiddenItemsIndex = udg_CP_HiddenItemsIndex - 1
    SetItemVisible(udg_CP_HiddenItems[udg_CP_HiddenItemsIndex], true)
    udg_CP_HiddenItems[udg_CP_HiddenItemsIndex] = null
    end
    udg_CP_PointIsWalkable = ((x2-x)*(x2-x) + (y2-y)*(y2-y) <= 100) and (not IsTerrainPathable(x, y, PATHING_TYPE_WALKABILITY)) 
end

